  1→//go:build e2e
  2→
  3→package agents
  4→
  5→import (
  6→	"context"
  7→	"encoding/json"
  8→	"errors"
  9→	"fmt"
 10→	"os"
 11→	"os/exec"
 12→	"strings"
 13→	"syscall"
 14→	"time"
 15→)
 16→
 17→func init() {
 18→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
 19→		return
 20→	}
 21→	if _, err := exec.LookPath("kiro-cli"); err != nil {
 22→		return
 23→	}
 24→	Register(&Kiro{})
 25→	// Kiro uses Amazon Q API which may have rate limits
 26→	RegisterGate("kiro", 1)
 27→}
 28→
 29→// Kiro implements the Agent interface for Amazon's Kiro CLI.
 30→type Kiro struct{}
 31→
 32→func (k *Kiro) Name() string               { return "kiro" }
 33→func (k *Kiro) Binary() string             { return "kiro-cli" }
 34→func (k *Kiro) EntireAgent() string        { return "kiro" }
 35→func (k *Kiro) PromptPattern() string      { return `!>` }
 36→func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }
 37→
 38→func (k *Kiro) IsTransientError(out Output, _ error) bool {
 39→	combined := out.Stdout + out.Stderr
 40→	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
 41→		if strings.Contains(strings.ToLower(combined), p) {
 42→			return true
 43→		}
 44→	}
 45→	return false
 46→}
 47→
 48→func (k *Kiro) Bootstrap() error {
 49→	// kiro-cli uses Amazon Q / Builder ID auth.
 50→	// On CI, ensure auth is available; locally, auth is handled by the desktop app.
 51→	if os.Getenv("CI") == "" {
 52→		return nil
 53→	}
 54→
 55→	if isTruthyEnvValue(os.Getenv("AMAZON_Q_SIGV4")) {
 56→		if err := validateKiroSIGV4Inputs(
 57→			os.Getenv("AWS_REGION"),
 58→			os.Getenv("AWS_ACCESS_KEY_ID"),
 59→			os.Getenv("AWS_SECRET_ACCESS_KEY"),
 60→		); err != nil {
 61→			return fmt.Errorf("kiro-cli sigv4 auth check failed: %w", err)
 62→		}
 63→		return nil
 64→	}
 65→
 66→	// Verify login status — fail fast if not authenticated.
 67→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 68→	defer cancel()
 69→	cmd := exec.CommandContext(ctx, "kiro-cli", "whoami", "-f", "json")
 70→	out, err := cmd.CombinedOutput()
 71→	if err != nil {
 72→		return fmt.Errorf(
 73→			"kiro-cli auth check failed (run `kiro-cli login --use-device-flow`): %s",
 74→			strings.TrimSpace(string(out)),
 75→		)
 76→	}
 77→	if err := validateKiroWhoamiJSON(out); err != nil {
 78→		return fmt.Errorf("kiro-cli auth check failed: %w", err)
 79→	}
 80→	return nil
 81→}
 82→
 83→func isTruthyEnvValue(v string) bool {
 84→	value := strings.TrimSpace(v)
 85→	if value == "" {
 86→		return false
 87→	}
 88→	lower := strings.ToLower(value)
 89→	return lower != "0" && lower != "false"
 90→}
 91→
 92→func validateKiroSIGV4Inputs(region, accessKeyID, secretAccessKey string) error {
 93→	if strings.TrimSpace(region) == "" {
 94→		return errors.New("AWS_REGION is required when AMAZON_Q_SIGV4 is enabled")
 95→	}
 96→	if strings.TrimSpace(accessKeyID) == "" {
 97→		return errors.New("AWS_ACCESS_KEY_ID is required when AMAZON_Q_SIGV4 is enabled")
 98→	}
 99→	if strings.TrimSpace(secretAccessKey) == "" {
100→		return errors.New("AWS_SECRET_ACCESS_KEY is required when AMAZON_Q_SIGV4 is enabled")
101→	}
102→	return nil
103→}
104→
105→func validateKiroWhoamiJSON(out []byte) error {
106→	var response struct {
107→		Account json.RawMessage `json:"account"`
108→	}
109→
110→	if err := json.Unmarshal(out, &response); err != nil {
111→		return fmt.Errorf("invalid whoami JSON: %w", err)
112→	}
113→	if len(response.Account) == 0 {
114→		return errors.New("account is missing")
115→	}
116→	if strings.EqualFold(strings.TrimSpace(string(response.Account)), "null") {
117→		return errors.New("account is null")
118→	}
119→	return nil
120→}
121→
122→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
123→	cfg := &runConfig{}
124→	for _, o := range opts {
125→		o(cfg)
126→	}
127→
128→	timeout := 2 * time.Minute
129→	if cfg.PromptTimeout > 0 {
130→		timeout = cfg.PromptTimeout
131→	}
132→	cmdCtx, cancel := context.WithTimeout(ctx, timeout)
133→	defer cancel()
134→
135→	// --no-interactive: runs a single prompt and exits; SIGV4 env vars
136→	// propagate naturally (no tmux env forwarding needed).
137→	// --trust-all-tools: auto-approve tool use (equivalent to -a in interactive mode).
138→	// --agent entire: activates the agent profile that contains our hooks.
139→	args := []string{"chat", "--no-interactive", "--trust-all-tools", "--agent", "entire"}
140→	if cfg.Model != "" {
141→		args = append(args, "--model", cfg.Model)
142→	}
143→	args = append(args, prompt)
144→
145→	// Build display args with quoted prompt for logging.
146→	displayArgs := make([]string, len(args))
147→	copy(displayArgs, args)
148→	displayArgs[len(displayArgs)-1] = fmt.Sprintf("%q", prompt)
149→
150→	cmd := exec.CommandContext(cmdCtx, k.Binary(), args...)
151→	cmd.Dir = dir
152→	cmd.Stdin = nil
153→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
154→	cmd.Cancel = func() error {
155→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
156→	}
157→	cmd.WaitDelay = 5 * time.Second
158→
159→	var stdout, stderr strings.Builder
160→	cmd.Stdout = &stdout
161→	cmd.Stderr = &stderr
162→
163→	err := cmd.Run()
164→	exitCode := 0
165→	if err != nil {
166→		exitErr := &exec.ExitError{}
167→		if errors.As(err, &exitErr) {
168→			exitCode = exitErr.ExitCode()
169→		} else {
170→			exitCode = -1
171→		}
172→	}
173→
174→	return Output{
175→		Command:  k.Binary() + " " + strings.Join(displayArgs, " "),
176→		Stdout:   stdout.String(),
177→		Stderr:   stderr.String(),
178→		ExitCode: exitCode,
179→	}, err
180→}
181→
182→func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
183→	return &KiroSession{kiro: k, dir: dir, ctx: ctx}, nil
184→}
185→
186→// KiroSession runs each Send as a separate --no-interactive command.
187→// SIGV4 auth does not work with the interactive TUI, so this approach
188→// runs one kiro-cli process per prompt (same pattern as setup-kiro-action).
189→type KiroSession struct {
190→	kiro       *Kiro
191→	dir        string
192→	ctx        context.Context
193→	lastOutput string
194→}
195→
196→func (s *KiroSession) Send(input string) error {
197→	out, err := s.kiro.RunPrompt(s.ctx, s.dir, input)
198→	s.lastOutput = out.Stdout + out.Stderr
199→	return err
200→}
201→
202→func (s *KiroSession) WaitFor(_ string, _ time.Duration) (string, error) {
203→	return s.lastOutput, nil
204→}
205→
206→func (s *KiroSession) Capture() string { return s.lastOutput }
207→func (s *KiroSession) Close() error    { return nil }
208→

